parameters.jsCode:
const input = $input.first().json;
const body = input.body || input;

const description = body.description || 'No description provided';
const username = body.username || body.userName || 'unknown_agent';
const userId = body.userId || '00000000';
const severity = (body.severity || 'medium').toLowerCase();
const logs = typeof body.logs === 'string' ? body.logs : JSON.stringify(body.logs || {}, null, 2);
const hardwareProfile = typeof body.hardwareProfile === 'string' ? body.hardwareProfile : JSON.stringify(body.hardwareProfile || 'Unknown HW', null, 2);
const timestamp = body.timestamp || new Date().toISOString();

const shortDesc = description.length > 50 ? description.substring(0, 47) + '...' : description;
const title = `[Bug] ${shortDesc} (via @${username})`;

return {
  title,
  description,
  username,
  userId,
  severity,
  logs,
  hardwareProfile,
  timestamp
};
